{
  "id": "1655efb9-f836-4378-b73f-0444432ede3c",
  "version": "1.8",
  "name": "VendorInvoiceProcessing",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Receive Invoice"
      },
      "inputs": {
        "entryPointId": "d036562e-6b25-4e29-ad71-192e8ba47dec",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "extractInvoiceFields",
      "type": "uipath.ixp.invoiceixp-cef0d447-ixp.ff973488-5d89-8035-86ac-f980b4be6deb-c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Extract Invoice Fields"
      },
      "inputs": {
        "model": {
          "id": "ff973488-5d89-8035-86ac-f980b4be6deb",
          "modelName": "invoiceixp-cef0d447-ixp",
          "modelDisplayName": "InvoiceIXP",
          "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "folderName": "Shared",
          "folderPath": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "description": ""
        },
        "modelName": "invoiceixp-cef0d447-ixp",
        "projectName": "invoiceixp-cef0d447-ixp",
        "versionTag": "",
        "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
        "folderName": "Shared",
        "fileRef": "=js:$vars.start.output.invoiceFile",
        "pageRange": "",
        "errorHandlingEnabled": true
      },
      "outputs": {
        "output": {
          "name": "output",
          "type": "object",
          "source": "=this.result",
          "var": "output",
          "schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "ExtractionResult": {
                "type": "object",
                "properties": {
                  "DocumentId": { "type": "string" },
                  "ResultsVersion": { "type": "integer" },
                  "ResultsDocument": {
                    "type": "object",
                    "properties": {
                      "Fields": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "FieldId": { "type": "string" },
                            "FieldName": { "type": "string" },
                            "FieldType": { "type": "string" },
                            "IsMissing": { "type": "boolean" },
                            "Values": { "type": "array", "items": { "type": "string" } },
                            "Confidence": { "type": "integer" }
                          }
                        }
                      },
                      "Tables": {
                        "type": "array",
                        "items": { "type": "object" }
                      }
                    }
                  }
                }
              },
              "ExtractorPayloads": { "type": "object" },
              "BusinessrulesResults": { "type": "array", "items": { "type": "object" } }
            }
          }
        },
        "error": {
          "type": "object",
          "description": "Error information if extraction fails",
          "source": "=Error",
          "var": "error",
          "schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "required": ["code", "message", "detail", "category", "status"],
            "properties": {
              "code": { "type": "string" },
              "message": { "type": "string" },
              "detail": { "type": "string" },
              "category": { "type": "string" },
              "status": { "type": "integer" }
            },
            "additionalProperties": false
          }
        }
      }
    },
    {
      "id": "buildInvoiceRecord",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Build Invoice Record"
      },
      "inputs": {
        "script": "const fields = ($vars.extractInvoiceFields.output.ExtractionResult?.ResultsDocument?.Fields) || [];\n\nfunction getField(name) {\n  const f = fields.find(f => f.FieldName === name);\n  return (f && !f.IsMissing && f.Values && f.Values.length > 0) ? f.Values[0] : null;\n}\n\nconst tables = ($vars.extractInvoiceFields.output.ExtractionResult?.ResultsDocument?.Tables) || [];\nconst lineItemsTable = tables.find(t => t.FieldName === 'LineItems' || t.FieldName === 'Line Items');\n\nreturn {\n  invoiceNumber: getField('InvoiceNumber') || getField('Invoice Number') || getField('invoice_number'),\n  invoiceDate: getField('InvoiceDate') || getField('Invoice Date') || getField('invoice_date'),\n  dueDate: getField('DueDate') || getField('Due Date') || getField('due_date'),\n  vendorName: getField('VendorName') || getField('Vendor Name') || getField('vendor_name') || getField('Supplier'),\n  vendorAddress: getField('VendorAddress') || getField('Vendor Address') || getField('vendor_address'),\n  billToName: getField('BillTo') || getField('Bill To') || getField('bill_to') || getField('CustomerName'),\n  subtotal: getField('Subtotal') || getField('Sub Total') || getField('subtotal'),\n  taxAmount: getField('TaxAmount') || getField('Tax Amount') || getField('tax_amount') || getField('VAT'),\n  totalAmount: getField('TotalAmount') || getField('Total Amount') || getField('total_amount') || getField('AmountDue') || getField('Amount Due'),\n  currency: getField('Currency') || getField('currency'),\n  purchaseOrderNumber: getField('PurchaseOrder') || getField('Purchase Order') || getField('po_number') || getField('PONumber'),\n  lineItems: lineItemsTable ? lineItemsTable.Values : [],\n  extractedAt: new Date().toISOString(),\n  documentId: $vars.extractInvoiceFields.output.ExtractionResult?.DocumentId\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Structured invoice record ready for downstream use",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Invoice Processed"
      },
      "outputs": {
        "invoiceRecord": {
          "source": "=js:$vars.buildInvoiceRecord.output"
        }
      }
    },
    {
      "id": "endExtractionError",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Extraction Failed"
      },
      "outputs": {
        "invoiceRecord": {
          "source": "=js:null"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-extract",
      "sourceNodeId": "start",
      "targetNodeId": "extractInvoiceFields",
      "sourceHandle": "output",
      "targetPort": "input"
    },
    {
      "id": "edge-extract-success-to-build",
      "sourceNodeId": "extractInvoiceFields",
      "targetNodeId": "buildInvoiceRecord",
      "sourceHandle": "success",
      "targetPort": "input"
    },
    {
      "id": "edge-extract-error-to-end",
      "sourceNodeId": "extractInvoiceFields",
      "targetNodeId": "endExtractionError",
      "sourceHandle": "error",
      "targetPort": "input"
    },
    {
      "id": "edge-build-to-end",
      "sourceNodeId": "buildInvoiceRecord",
      "targetNodeId": "end",
      "sourceHandle": "success",
      "targetPort": "input"
    }
  ],
