147	        "label": "Build Invoice Record"
148	      },
149	      "inputs": {
150	        "script": "const fields = ($vars.extractInvoiceFields.output.ExtractionResult?.ResultsDocument?.Fields) || [];\n\nfunction getField(name) {\n  const f = fields.find(f => f.FieldName === name);\n  return (f && !f.IsMissing && f.Values && f.Values.length > 0) ? f.Values[0] : null;\n}\n\nconst tables = ($vars.extractInvoiceFields.output.ExtractionResult?.ResultsDocument?.Tables) || [];\nconst lineItemsTable = tables.find(t => t.FieldName === 'LineItems' || t.FieldName === 'Line Items');\n\nreturn {\n  invoiceNumber: getField('InvoiceNumber') || getField('Invoice Number') || getField('invoice_number'),\n  invoiceDate: getField('InvoiceDate') || getField('Invoice Date') || getField('invoice_date'),\n  dueDate: getField('DueDate') || getField('Due Date') || getField('due_date'),\n  vendorName: getField('VendorName') || getField('Vendor Name') || getField('vendor_name') || getField('Supplier'),\n  vendorAddress: getField('VendorAddress') || getField('Vendor Address') || getField('vendor_address'),\n  billToName: getField('BillTo') || getField('Bill To') || getField('bill_to') || getField('CustomerName'),\n  subtotal: getField('Subtotal') || getField('Sub Total') || getField('subtotal'),\n  taxAmount: getField('TaxAmount') || getField('Tax Amount') || getField('tax_amount') || getField('VAT'),\n  totalAmount: getField('TotalAmount') || getField('Total Amount') || getField('total_amount') || getField('AmountDue') || getField('Amount Due'),\n  currency: getField('Currency') || getField('currency'),\n  purchaseOrderNumber: getField('PurchaseOrder') || getField('Purchase Order') || getField('po_number') || getField('PONumber'),\n  lineItems: lineItemsTable ? lineItemsTable.Values : [],\n  extractedAt: new Date().toISOString(),\n  documentId: $vars.extractInvoiceFields.output.ExtractionResult?.DocumentId\n};"
151	      },
152	      "outputs": {
153	        "output": {
154	          "type": "object",
155	          "description": "Structured invoice record ready for downstream use",
156	          "source": "=result.response",
157	          "var": "output"
158	        }
159	      }
